const descriptions={music:['YOUR LIBRARY, FRONT AND CENTER','Every track. Right here.','Bring the audio files on your device together in one place. Browse your library or search for the song you came for.'],albums:['THE COMPLETE LISTENING EXPERIENCE','Some records deserve every track.','Browse your albums and return to the records you love. From the opening track to the final note, keep the collection together.'],artists:['FAMILIAR VOICES. NEW FAVORITES.','Find your kind of sound.','Explore your library by artist. Spend a little more time with the voices and sounds that make your collection yours.'],playlists:['A SOUNDTRACK FOR EVERY DAY','Put your favorites in good company.','Create your own playlists and save favorites. A morning routine, a long journey, or just the songs you keep coming back to.'],offline:['WITH YOU, WHEREVER YOU GO','No signal. Still your music.','Play audio stored on your device without an internet connection. Ads and optional online features need a connection.']};
const tabs=[...document.querySelectorAll('[data-tab]')];function activate(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1});const [label,title,copy]=descriptions[tab.dataset.tab];document.querySelector('.detail-label').textContent=label;document.querySelector('#detail-title').textContent=title;document.querySelector('#detail-copy').textContent=copy;document.querySelector('#collection-panel').setAttribute('aria-labelledby',tab.id)}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>activate(tab));tab.addEventListener('keydown',event=>{let next;if(['ArrowDown','ArrowRight'].includes(event.key))next=(index+1)%tabs.length;if(['ArrowUp','ArrowLeft'].includes(event.key))next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();activate(tabs[next]);tabs[next].focus()}})});
